const rows=Array.isArray($json.data)?$json.data:[];
const stable=new Set(['USDT','USDC','DAI','FDUSD','TUSD','USDP','EURT']);
const banned=/(3L|3S|5L|5S|UP|DOWN|BULL|BEAR)$/i;
let list=rows.filter(t=>{const id=String(t.instId||''); if(!id.endsWith('-USDT')) return false; const base=id.split('-')[0]; if(stable.has(base)) return false; if(banned.test(base)) return false; return Number(t.volCcy24h||0)>0 && Number(t.last||0)>0;});
list.sort((a,b)=>Number(b.volCcy24h||0)-Number(a.volCcy24h||0));
list=list.slice(0,20);
const openPair=s.position?.pair; if(openPair && !list.some(t=>t.instId===openPair)){const t=rows.find(x=>x.instId===openPair); if(t) list.push(t);}
return list.map(t=>({json:{instId:t.instId,last:Number(t.last),volCcy24h:Number(t.volCcy24h||0)}}));

const s=$getWorkflowStaticData('global'); const now=Date.now(); s.mode='LIVE_ASSIST'; s.lastScanAt=new Date().toISOString();
if(s.pendingTrade?.status==='pending' && now<Number(s.pendingTrade.expiresAt||0)) return [{json:{proposalCreated:false,reason:'PENDING_EXISTS'}}];
if(s.pendingTrade?.status==='pending') s.pendingTrade.status='expired';
const inputs=$input.all(); const meta=$('JOHN Top 20 Liquid').all(); const candidates=[]; let openExit=null;
function metrics(raw){const c=raw.slice().reverse().map(x=>Number(x[4])).filter(x=>Number.isFinite(x)&&x>0); if(c.length<20)return null; const sma=n=>c.slice(-n).reduce((a,b)=>a+b,0)/n; const f=sma(5), slow=sma(20), last=c.at(-1), prev=c.at(-2); let g=0,l=0; for(let i=Math.max(1,c.length-14);i<c.length;i++){const d=c[i]-c[i-1]; if(d>0)g+=d; else l-=d;} const rs=l===0?100:(g/14)/(l/14); const rsi=100-(100/(1+rs)); const mom=(last-prev)/prev; return {f,slow,last,rsi,mom};}
for(let i=0;i<inputs.length;i++){const instId=meta[i]?.json?.instId; const raw=inputs[i]?.json?.data; if(!instId||!Array.isArray(raw)) continue; const m=metrics(raw); if(!m)continue;
 if(s.position?.pair===instId){ if(m.last<=Number(s.position.stopLoss)||m.last>=Number(s.position.takeProfit)||m.f<m.slow*.999||m.rsi<45){openExit={instId,m,reason:m.last<=Number(s.position.stopLoss)?'Stop loss':m.last>=Number(s.position.takeProfit)?'Take profit':'Exit signal · RSI '+m.rsi.toFixed(1)};} }
 if(!s.position && m.f>m.slow*1.001 && m.mom>0.001 && m.rsi>=52 && m.rsi<=68){const conf=Math.min(.95,.66+(m.f/m.slow-1)*25+m.mom*18); candidates.push({instId,m,confidence:Number(conf.toFixed(2))});}
}
let side=null,pair=null,m=null,confidence=.7,reason='',amount=5;
if(openExit){side='sell';pair=openExit.instId;m=openExit.m;confidence=.78;reason=openExit.reason;amount=Number(s.position.amountQuote||5);} else if(candidates.length){candidates.sort((a,b)=>b.confidence-a.confidence); const c=candidates[0]; side='buy';pair=c.instId;m=c.m;confidence=c.confidence;amount=confidence>=.80?10:5;reason='Bullish 15m · RSI '+m.rsi.toFixed(1)+' · momentum '+(m.mom*100).toFixed(2)+'%';}
if(!side){s.lastMarket={at:s.lastScanAt,marketOk:true,universe:meta.length}; return [{json:{proposalCreated:false,reason:'NO_SIGNAL',scanned:meta.length}}];}
const p={id:'J'+now+(side==='buy'?'B':'S'),side,pair,amountQuote:Math.min(10,Math.max(5,amount)),entry:m.last,stopLoss:side==='buy'?Number((m.last*.985).toFixed(8)):Number(s.position?.stopLoss||0),takeProfit:side==='buy'?Number((m.last*1.03).toFixed(8)):Number(s.position?.takeProfit||0),confidence,reason,createdAt:now,expiresAt:now+20*60*1000,status:'pending'};
s.pendingTrade=p; s.lastMarket={at:s.lastScanAt,marketOk:true,universe:meta.length,pair,last:m.last,rsi:m.rsi}; s.lastEvent={at:new Date().toISOString(),message:side.toUpperCase()+' proposal '+pair}; return [{json:{proposalCreated:true,proposal:p}}];

